    :param maxsize: Maximum number of items kept in cache. Above this,
                    the oldest items will be discarded.
    :param typed: Determines whether the memoized function will be
                  accesible by passing in the same types in the
                  (*args, **kwargs) format.
    """

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key = (type(args), args, kwargs)
            else:
                key = (args, kwargs)

            if key in wrapper.cache:
                return wrapper.cache[key]
            else:
                value = func(*args, **kwargs)
                wrapper.cache[key] = value
                return value

        wrapper.cache = OrderedDict()
        wrapper.__wrapped__ = func
        return wrapper

    return decorator

