def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    def decorator(func):
        _lfu = {}
        for i, key in enumerate(func.cache.keys()):
            if i >= maxsize:
                # Remove the least frequently used item
                del _lfu[key]
            if typed:
                _lfu[key] = (1, func.cache[key])
            else:
                _lfu[key] = (0, func.cache[key])
        return _lfu[key]

    return decorator

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = dict()
        freq = dict()

        def wrapper(*args):
            key = (args, frozenset(args) if typed else None)
            if key not in cache:
                result = func()
                cache[key] = result
                freq[key] = 1
                while len(cache) > maxsize:
                    evicted_key = min(freq, key=freq.get)
                    freq.pop(evicted_key)
                    cache.pop(evicted_key)
            else:
                freq[key] += 1
            return cache[key]
        return wrapper
    return decorator

