def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Initialize an empty set to store the minimal bases
    minimal_bases = set()
    # Iterate over the input list of base classes
    for base in classes:
        # Check if the base class is already in the set of minimal bases
        if base not in minimal_bases:
            # If not, add it to the set of minimal bases
            minimal_bases.add(base)
            # Iterate over the remaining base classes
            for other_base in classes[classes.index(base) + 1:]:
                # Check if the other base class is a subclass of the current base class
                if issubclass(other_base, base):
                    # If it is, remove the other base class from the set of minimal bases
                    minimal_bases.remove(other_base)
    # Return the set of minimal bases as a list
    return list(minimal_bases)

