            if isinstance(s, (tuple, list)):
                normalized.append(tuple(s))
            elif isinstance(s, Declaration):
                normalized.append(s.normalize())
            elif isinstance(s, str):
                normalized.append(parse_interface(s).normalize())
            elif isinstance(s, Declarations):
                normalized.append(s.normalize())
