def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    if not commands:
        raise ValueError("No commands given.")

    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("Invalid working dir provided: {}".format(cwd))

    for command in commands:
        if not command:
            continue

        shell_command = shlex.split(command)
        if verbose:
            click.echo(f"Running command: {command}")

        stderr = subprocess.DEVNULL if hide_stderr else None
        p = subprocess.Popen(shell_command, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=stderr, cwd=cwd, env=env)
        p.stdin.write(args)
        try:
            output = p.communicate(timeout=None)[0].decode("utf-8")
        except subprocess.TimeoutExpired as e:
            p.kill()
            raise e

        if verbose:
            click.echo(output)

        return output

