def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Arguments:
        size (str): A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    if size.endswith('KB'):
        return int(float(size[:-2]) * 1000)
    elif size.endswith('MB'):
        return int(float(size[:-2]) * 1000 ** 2)
    elif size.endswith('GB'):
        return int(float(size[:-2]) * 1000 ** 3)
    elif size.endswith('TB'):
        return int(float(size[:-2]) * 1000 ** 4)
    elif size.endswith('PB'):
        return int(float(size[:-2]) * 1000 ** 5)
    elif size.endswith('EB'):
        return int(float(size[:-2]) * 1000 ** 6)
    else:
        return int(float(size))

