    bytes_per_unit = {
        "": 1,
        "K": 1000,
        "M": 1000**2,
        "G": 1000**3
    }

    unit = size[-1]
    if unit in bytes_per_unit:
        return float(size[:-1]) * bytes_per_unit[unit]
