def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list) or not all([isinstance(c, str) for c in alphabet]):
        raise ValueError("alphabet must be a list of characters")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    if padding is not None and padding < 0:
        raise ValueError("padding must be a positive integer")

    if number == 0:
        return alphabet[0]

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    digits.reverse()
    result = "".join(digits)

    if padding is not None and len(result) < padding:
        result = "0" * (padding - len(result)) + result

    return result

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    if padding is not None and len(alphabet) < padding:
        raise ValueError("Alphabet size must be greater than or equal to padding")

    if number < 0:
        raise ValueError("Input number must be non-negative")

    if padding is None:
        padding = 0

    result = []
    while number > 0:
        remainder = number % len(alphabet)
        number //= len(alphabet)
        result.append(alphabet[remainder])
        if number == 0:
            break

    return "".join(result[::-1])

