def make_find_paths(find_paths):
    transformed_paths = []
    for path in find_paths:
        if "://" in path or re.search(r"[*?\[]", path):
            # If the path contains a protocol, or asterisks, question marks, or square brackets,
            # we assume it's a glob pattern and pass it through untouched.
            transformed_paths.append(path)
        else:
            # Otherwise, construct a glob pattern by adding 'sh:**/*' at the beginning and '*/**' at the end.
            transformed_paths.append("sh:**/*{}*".format(path))
    return transformed_paths

