def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()
    for node in graph.nodes():
        in_parenthesis = 0
        for successor in graph.successors(node):
            if successor != node:
                in_parenthesis += 1
                if successor in roots:
                    # node is a descendant of a root
                    roots.remove(successor)
                if successor in roots:
                    # successor is a root, add node to the roots set
                    roots.add(node)
    return roots

