def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not text:
        return text
    paragraphs = text.split('\n\n')
    for paragraph in paragraphs:
        sentences = paragraph.split('.')
        for sentence in sentences:
            words = sentence.split()
            for word in words:
                # Check if the word is a link
                if word.startswith('http') and word.endswith('com'):
                    # Add some attributes to the link
                    word = f'[{word}](Link to {word})'
                elif word.startswith('http') and word.endswith('org'):
                    # Add some more attributes to the link
                    word = f'[{word}](Link to {word}, with a hint of rainbow)'
                elif word.startswith('http') and word.endswith('edu'):
                    # Add some attributes to the link
                    word = f'[{word}](Link to {word}, but really, it\'s not that great)'
                sentences.append(word)
        paragraphs.append('. '.join(sentences))
    return '\n\n'.join(paragraphs)

