def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Verify the signature using the public key
    if not verify(signature, public_key, doc):
        raise ValueError("Invalid signature")
    # Check that all signatures are unique
    for el in doc.findall(".//Signature"):
        if doc.find(el) != el:
            raise ValueError("Duplicate signature")
    # Check that all signed elements have a unique ID attribute
    for el in doc.findall(".//[contains(@sig:id)]"):
        if doc.find(".//*[@sig:id='%s']" % el.get("sig:id")) != el:
            raise ValueError("Duplicate ID attribute")

