    import xml.etree.ElementTree as ET

    if not document:
        raise ValueError("Invalid input, cannot parse empty document")

    if document.startswith("<xrd"):
        # XRD format
        root = ET.fromstring(document)
        xrd = root.find(".//{http://docs.oasis-open.org/ns/xri}XRD")
        if xrd is None:
            raise ValueError("Invalid XRD format, missing <XRD> element")
        ret = {k.get("type"): v.text for k, v in xrd.items()}
    else:
        # JSON format
        ret = json.loads(document)

    return ret

