def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content or not isinstance(spec_content, dict):
        raise IRValidatorException("Spec file content is not a dictionary.")

    if "namespace" not in spec_content:
        raise IRValidatorException("'namespace' is missing in spec file content.")

    if "class" not in spec_content:
        raise IRValidatorException("'class' is missing in spec file content.")

    if "variables" not in spec_content:
        raise IRValidatorException("'variables' is missing in spec file content.")

    expected_variables = {key: self.DEFAULT_VAR_SCHEMA for key in self.ALLOWED_VARIABLES}

    for var, val_schema in spec_content["variables"].items():
        if var not in expected_variables.keys():
            raise IRValidatorException(f"Unexpected variable '{var}' in spec file.")

        if not isinstance(val_schema, dict):
            raise IRValidatorException(f"'{var}' is not a dictionary.")

        for key, val in val_schema.items():
            if key not in expected_variables[var]:
                raise IRValidatorException(f"Unexpected key '{key}' in value schema of variable '{var}'.")

            if val not in expected_variables[var][key]:
                raise IRValidatorException(f"Unexpected value '{val}' for key '{key}' in value schema of variable '{var}'.")

    return spec_content

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """

        if not yaml_file:
            raise ValueError("No YAML file provided.")

        try:
            with open(yaml_file, "r") as f:
                data = yaml.load(f, Loader=yamlloader.Loader)
        except FileNotFoundError:
            raise ValueError(f"YAML file '{yaml_file}' not found.")
        except yaml.YAMLError as e:
            raise ValueError(f"Invalid YAML file: {e}")

        # validate that required data is present in the file
        required_data = ["resource_type", "source_name", "dataset_ids", "coords", "year", "month", "day",
                         "processing_datetime"]
        for field in required_data:
            if field not in data:
                raise IRValidatorException(f"'{field}' not found in YAML file '{yaml_file}'.")

        return data

