def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Arguments:
        parser_dict (dict): The parser dictionary.

    Returns:
        dict: The resolved parser dictionary.
    """
    for group_name, group_values in parser_dict.items():
        if group_values is not None and 'properties' in group_values:
            group_values['properties'] = [(key, group_values['properties'][key]) for key in group_values['properties'] if key not in self.groups]
        if group_name in self.groups:
            for key, value in group_values.items():
                self.groups[group_name][key] = value
        else:
            self.groups[group_name] = group_values
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not parser_dict:
        return

    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)

        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    self._include_groups(item)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    # Get the included dictionaries
    included_dicts = []
    for include in parser_dict.get("include", []):
        # Check if the include is a relative path
        if include.startswith("/"):
            # Use the full path
            included_dicts.append(self._get_document(include))
        else:
            # Use the relative path
            included_dicts.append(self._get_document(self.doc.parent + include, self.doc.Mappings))

    # Add the included dictionaries to the parser dict
    for included_dict in included_dicts:
        parser_dict.update(included_dict)

    return parser_dict

