def _get_conditionally_required_args(command_name, options_spec, args):
    result = []
    for arg in args:
        if arg['position'] and not arg['is_optional'] and arg['required_when']:
            required = arg['required_when']
            if isinstance(required, str):
                match_names = required.split(',')
                if arg['name'] in match_names:
                    result.append(arg['name'])
            elif isinstance(required, list):
                for match in required:
                    if arg['name'] in match['name']:
                        result.append(arg['name'])
                        break
    return result

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name
    :param options_spec: the list of command spec options
    :param args: the received input arguments
    :return: list, list of argument names with matched `required_when` condition
    """
    conditions_met = []
    for option in options_spec:
        if 'required_when' in option:
            if option['required_when'](options_spec, args):
                conditions_met.append(option['name'])
    return conditions_met

