def _convert_non_cli_args(self, parser_name, values_dict):
    for arg in values_dict:
        if arg in self.PARSERS[parser_name]['arguments']:
            values_dict[arg] = self._convert_type(arg, values_dict)
    return values_dict

def _convert_type(self, arg, values_dict):
    arg_type = self.PARSERS[self.PARSERS[parser_name]['arguments'][arg]]['type']
    if arg_type == 'string':
        return values_dict[arg]
    elif arg_type == 'int':
        return int(values_dict[arg])
    elif arg_type == 'float':
        return float(values_dict[arg])
    elif arg_type == 'bool':
        return bool(values_dict[arg])
    else:
        raise ValueError(f'Unknown argumnt type {arg_type} for argument {arg}')

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Retrieve the CLI parameters specification for the provided parser_name
    cli_args = CLI_ARGUMENTS.get(parser_name, {})

    # Iterate over the argument specification and convert each argument value to its required type
    for arg in cli_args:
        value = values_dict.get(arg)
        if value:
            if arg in STRING_ARGS:
                values_dict[arg] = str(value)
            elif arg in BOOL_ARGS:
                values_dict[arg] = bool(value)
            elif arg in INTEGER_ARGS:
                values_dict[arg] = int(value)
            elif arg in FLOAT_ARGS:
                values_dict[arg] = float(value)
            elif arg in LIST_ARGS:
                values_dict[arg] = list(value)
            else:
                raise ValueError(f"Unknown argument type for argument '{arg}'")

    # Return the updated values_dict
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    plugin_spec_file = os.path.join(plugin_dir, "plugin.json")
    if os.path.exists(plugin_spec_file):
        with open(plugin_spec_file, "r") as f:
            plugin_spec = json.loads(f.read())
    plugin_spec_dir = os.path.join(plugin_dir, "plugin.d")
    if os.path.isdir(plugin_spec_dir):
        for f in os.listdir(plugin_spec_dir):
            with open(os.path.join(plugin_spec_dir, f), "r") as f:
                plugin_spec.update(json.loads(f.read()))
    return plugin_spec

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Load the plugin specification
    with open(os.path.join(plugin_dir, "plugin.json"), "r") as f:
        spec = json.load(f)

    # Create a flat dictionary
    flatten_dict = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            for k, v in value.items():
                flatten_dict[f"{key}.{k}"] = v
        else:
            flatten_dict[key] = value

    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    flattened_dict = {}
    with open(plugin_dir, "r") as f:
        plugin_spec = yaml.safe_load(f)
        for key, value in plugin_spec.items():
            if isinstance(value, dict):
                for sub_key, sub_value in value.items():
                    flattened_dict["{}.{}".format(key, sub_key)] = sub_value
            else:
                flattened_dict[key] = value
    return flattened_dict

